item.description:
已配置 ADS 的接口参考。请求属性是带类型的数组，诊断响应属性是对象。
请配置安全连接与端点访问控制。这是接口契约，speedle.io 不托管授权后端。
              (function() { var url = "\/swagger\/policy-check.zh.yaml"; const ui = SwaggerUIBundle({ url: url, dom_id: '#swagger-ui', deepLinking: true, presets: [ SwaggerUIBundle.presets.apis ], plugins: [ SwaggerUIBundle.plugins.DownloadUrl ], validatorUrl: null, layout: "BaseLayout" }) window.ui = ui })();
